def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for char in text:
        if char.isalpha():
            if char.isupper():
                base = ord('A')
            else:
                base = ord('a')
            result += chr((ord(char) - base + shift) % 26 + base)
        else:
            result += char
    return result

def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for c in text:
        if 'a' <= c <= 'z':
            new_ord = (ord(c) - ord('a') + shift) % 26 + ord('a')
            result += chr(new_ord)
        elif 'A' <= c <= 'Z':
            new_ord = (ord(c) - ord('A') + shift) % 26 + ord('A')
            result += chr(new_ord)
        else:
            result += c
    return result

def fibonacci(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

